import{_ as t,o as a,c as s,a5 as n}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"设计方法论","description":"系统设计不是灵感创作，是有章可循的工程过程。","frontmatter":{},"headers":[],"relativePath":"engineering/05-system-design/chapter-01-design-methodology.md","filePath":"engineering/05-system-design/chapter-01-design-methodology.md"}'),i={name:"engineering/05-system-design/chapter-01-design-methodology.md"};function d(l,e,r,g,o,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="设计方法论" tabindex="-1" data-src-line="1" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">设计方法论 <a class="header-anchor" href="#设计方法论" aria-label="Permalink to &quot;设计方法论&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><p data-src-line="3" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">系统设计不是灵感创作，是有章可循的工程过程。</p></blockquote><h2 id="_1-系统设计四步法" tabindex="-1" data-src-line="5" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">1. 系统设计四步法 <a class="header-anchor" href="#_1-系统设计四步法" aria-label="Permalink to &quot;1. 系统设计四步法&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 需求澄清 → 明确功能和非功能需求</span></span>
<span class="line"><span>2. 高层设计 → 画架构图，确定核心组件</span></span>
<span class="line"><span>3. 详细设计 → 深入关键组件的技术方案</span></span>
<span class="line"><span>4. 权衡讨论 → 讨论设计决策的 trade-off</span></span></code></pre></div><h2 id="_2-需求澄清" tabindex="-1" data-src-line="14" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">2. 需求澄清 <a class="header-anchor" href="#_2-需求澄清" aria-label="Permalink to &quot;2. 需求澄清&quot;">​</a></h2><h3 id="功能需求" tabindex="-1" data-src-line="16" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">功能需求 <a class="header-anchor" href="#功能需求" aria-label="Permalink to &quot;功能需求&quot;">​</a></h3><ul data-src-line="18" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><li data-src-line="18" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">核心功能是什么？</li><li data-src-line="19" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">用户场景有哪些？</li><li data-src-line="20" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">API 接口怎么设计？</li></ul><h3 id="非功能需求" tabindex="-1" data-src-line="22" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">非功能需求 <a class="header-anchor" href="#非功能需求" aria-label="Permalink to &quot;非功能需求&quot;">​</a></h3><table tabindex="0"><thead data-src-line="24" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><tr data-src-line="24" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><th style="text-align:left;">维度</th><th style="text-align:left;">需要问的问题</th></tr></thead><tbody data-src-line="26" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><tr data-src-line="26" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">并发量</td><td style="text-align:left;">QPS 是多少？峰值是多少？</td></tr><tr data-src-line="27" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">数据量</td><td style="text-align:left;">存储多少数据？增长速度？</td></tr><tr data-src-line="28" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">延迟</td><td style="text-align:left;">P99 延迟要求？</td></tr><tr data-src-line="29" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">可用性</td><td style="text-align:left;">几个 9？能容忍多长停机？</td></tr><tr data-src-line="30" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">一致性</td><td style="text-align:left;">强一致还是最终一致？</td></tr></tbody></table><h2 id="_3-高层设计" tabindex="-1" data-src-line="32" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">3. 高层设计 <a class="header-anchor" href="#_3-高层设计" aria-label="Permalink to &quot;3. 高层设计&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同步读链路（常见读路径）：Client → LB → App Server → Cache</span></span>
<span class="line"><span>            缓存未命中 → DB（回源后回填 Cache）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>异步处理链路：App Server → Message Queue → Worker</span></span></code></pre></div><p data-src-line="41" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">核心步骤：</p><ol data-src-line="43" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><li data-src-line="43" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">画数据流图</li><li data-src-line="44" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">确定核心组件</li><li data-src-line="45" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">定义组件间接口</li><li data-src-line="46" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">估算容量</li></ol><h2 id="_4-容量估算" tabindex="-1" data-src-line="48" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">4. 容量估算 <a class="header-anchor" href="#_4-容量估算" aria-label="Permalink to &quot;4. 容量估算&quot;">​</a></h2><p data-src-line="50" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">容量估算用于在方案初期建立数量级直觉，结论是粗估而非精确值。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>假设：DAU = 1000万，每人每天 10 次操作</span></span>
<span class="line"><span>  平均 QPS = 1000万 × 10 / 86400 ≈ 1200 QPS（全天请求均摊到 86400 秒）</span></span>
<span class="line"><span>  峰值 QPS ≈ 3 × 1200 = 3600 QPS（峰值系数 3 只是示例假设）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>存储：每条记录 1KB，每天 1亿条</span></span>
<span class="line"><span>  日增量 = 1亿 × 1KB = 100GB/天</span></span>
<span class="line"><span>  年增量 = 100GB × 365 = 36TB/年</span></span></code></pre></div><ul data-src-line="62" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><li data-src-line="62" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">峰值系数 3 不是通用常数，实际峰值取决于活跃时段与业务事件，需用压测或历史流量标定。</li><li data-src-line="63" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">1KB 是逻辑记录大小，实际存储占用还需计入索引、副本、日志与保留周期。</li><li data-src-line="64" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">估算结果要回到单实例承载能力与压测数据，验证实例数量与冗余是否够用，方法见 <a href="./chapter-02-high-concurrency.html">高并发设计</a>。</li></ul><h2 id="_5-常见设计模式" tabindex="-1" data-src-line="66" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">5. 常见设计模式 <a class="header-anchor" href="#_5-常见设计模式" aria-label="Permalink to &quot;5. 常见设计模式&quot;">​</a></h2><table tabindex="0"><thead data-src-line="68" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><tr data-src-line="68" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><th style="text-align:left;">问题</th><th style="text-align:left;">方案</th></tr></thead><tbody data-src-line="70" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><tr data-src-line="70" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">高并发读</td><td style="text-align:left;">缓存 + CDN + 读写分离</td></tr><tr data-src-line="71" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">高并发写</td><td style="text-align:left;">消息队列 + 异步处理</td></tr><tr data-src-line="72" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">大数据量</td><td style="text-align:left;">分库分表 + 冷热分离</td></tr><tr data-src-line="73" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">高可用</td><td style="text-align:left;">主从 + 自动故障转移</td></tr><tr data-src-line="74" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">低延迟</td><td style="text-align:left;">缓存 + 本地计算</td></tr></tbody></table><p data-src-line="76" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">上表是常见思路，不是一一对应的充分条件。消息队列能削峰解耦，却不会提升数据库的持续写入能力，消费速度长期低于生产速度时积压只会增长；主从加自动切换也不等于高可用，复制延迟、脑裂与切换期间的写入丢失仍需单独应对。选型要回到吞吐、延迟、一致性、运维复杂度与团队能力等维度综合判断，详见 <a href="./chapter-02-high-concurrency.html">高并发设计</a>、<a href="./chapter-03-high-availability.html">高可用设计</a>、<a href="./chapter-04-high-performance.html">高性能设计</a>、<a href="./chapter-05-scalability.html">可扩展设计</a>。</p><h2 id="_6-权衡讨论" tabindex="-1" data-src-line="78" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">6. 权衡讨论 <a class="header-anchor" href="#_6-权衡讨论" aria-label="Permalink to &quot;6. 权衡讨论&quot;">​</a></h2><p data-src-line="80" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">每个设计决策都有 trade-off：</p><table tabindex="0"><thead data-src-line="82" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><tr data-src-line="82" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><th style="text-align:left;">决策</th><th style="text-align:left;">选择 A</th><th style="text-align:left;">选择 B</th></tr></thead><tbody data-src-line="84" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><tr data-src-line="84" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">数据库</td><td style="text-align:left;">MySQL（成熟）</td><td style="text-align:left;">TiDB（分布式）</td></tr><tr data-src-line="85" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">缓存</td><td style="text-align:left;">Redis（功能丰富）</td><td style="text-align:left;">Memcached（极简）</td></tr><tr data-src-line="86" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">消息队列</td><td style="text-align:left;">RabbitMQ（低延迟）</td><td style="text-align:left;">Kafka（高吞吐）</td></tr><tr data-src-line="87" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md"><td style="text-align:left;">一致性</td><td style="text-align:left;">强一致</td><td style="text-align:left;">最终一致</td></tr></tbody></table><p data-src-line="89" data-src-file="engineering/05-system-design/chapter-01-design-methodology.md">表中标签只提示最突出的差异，不是选型的全部依据。强一致与最终一致不是「安全」与「性能」的对立，而是读写语义、故障模型与延迟预算的综合权衡；MySQL 与 TiDB 的取舍还要看数据规模、事务需求与运维成本。一致性模型见 <a href="./chapter-06-distributed-theory.html">CAP 理论与 BASE 理论</a>。</p>`,24)])])}const p=t(i,[["render",d]]);export{m as __pageData,p as default};
